import{authService}from "../services/auth-service.js?v=2";import{renderNavigation,updateActiveNavItem}from "./navigation.js?v=13";const routes={"/":{screen:"onboarding",authRequired:false,fullScreen:true,},"/onboarding":{screen:"onboarding",authRequired:false,fullScreen:true,},"/login":{screen:"auth",subview:"login",authRequired:false,fullScreen:true,},"/register":{screen:"auth",subview:"register",authRequired:false,fullScreen:true,},"/dashboard":{screen:"dashboard",authRequired:false},"/matchmaking":{screen:"matchmaking",subview:"matchmaking",authRequired:false,fullScreen:true},"/market":{screen:"market",authRequired:false},"/comparison":{screen:"comparison",authRequired:false},"/lineup":{screen:"lineup",authRequired:false},"/match/live":{screen:"match",subview:"live-match",authRequired:false,fullScreen:true},"/match/result":{screen:"match",subview:"match-result",authRequired:false,fullScreen:true},"/history":{screen:"history",authRequired:false},"/ranking":{screen:"ranking",authRequired:false,fullScreen:false,},"/profile":{screen:"profile",authRequired:true},"/admin/players":{screen:"admin",authRequired:true,adminOnly:true},};let isRouterInitialized=false;export function initRouter(){if(isRouterInitialized)return;isRouterInitialized=true;window.router={navigate:navigateTo,current:getCurrentRoute};window.addEventListener("popstate",handleLocation);window.addEventListener("hashchange",handleLocation);window.addEventListener("pageshow",(event)=>{if(event.persisted){handleLocation();}});document.body.addEventListener("click",(e)=>{if(e.target.closest(".match-details-link")){e.preventDefault();return;}
const link=e.target.closest("a[data-link]");if(link){e.preventDefault();navigateTo(link.getAttribute("href"));}});handleLocation();}
export function navigateTo(url){if(window.location.search){const isIndexFile=window.location.pathname.includes("index.html")||window.location.pathname.endsWith("/public/");const cleanUrl=isIndexFile?window.location.pathname+"#"+url:url;window.history.replaceState({},"",cleanUrl);handleLocation();}else if(window.location.pathname.includes("index.html")||window.location.pathname.endsWith("/public/")||window.location.hash.startsWith("#/")){const targetHash="#"+url;if(window.location.hash!==targetHash){window.location.hash=targetHash;}else{handleLocation();}}else{const currentFullUrl=window.location.pathname+window.location.search;if(currentFullUrl!==url){window.history.pushState({},"",url);}
handleLocation();}}
export function getCurrentRoute(){if(window.location.hash&&window.location.hash.length>1){const rawHash=window.location.hash.slice(1).split("?")[0];return rawHash.startsWith("/")?rawHash:"/"+rawHash;}
const urlParams=new URLSearchParams(window.location.search);const explicit=urlParams.get("screen")||urlParams.get("route");if(explicit){return explicit.startsWith("/")?explicit:"/"+explicit;}
let path=window.location.pathname||"/";if(path.includes("index.html")||path.endsWith("/public/")){return "/";}
return path;}
function updateBrowserUrl(newPath){if(window.location.pathname.includes("index.html")||window.location.pathname.endsWith("/public/")){if(window.location.hash!=="#"+newPath){window.location.hash=newPath;}}else if(window.location.pathname!==newPath){window.history.replaceState({},"",newPath);}}
async function handleLocation(){const urlParams=new URLSearchParams(window.location.search);if(urlParams.get("reset")==="true"){localStorage.removeItem("auth_token");localStorage.removeItem("access_token");localStorage.removeItem("user");localStorage.removeItem("hasSeenOnboarding");localStorage.removeItem("fantasy_active_squad");localStorage.removeItem("fantasy_player_stats");const cleanPath=window.location.pathname||"/";window.history.replaceState({},"",cleanPath);}
const isDirectTest=urlParams.get("test")==="true"||urlParams.get("home")==="true"||urlParams.get("screen")==="dashboard"||window.location.hash.includes("dashboard");if(isDirectTest){localStorage.setItem("hasSeenOnboarding","true");if(!localStorage.getItem("auth_token")&&!localStorage.getItem("access_token")){localStorage.setItem("auth_token","dev-test-token");localStorage.setItem("user",JSON.stringify({name:"Mánager Leyenda",email:"manager@fantasy.com"}));}}
let path=getCurrentRoute();const hasSeenOnboarding=localStorage.getItem("hasSeenOnboarding")==="true";const authToken=localStorage.getItem("auth_token")||localStorage.getItem("access_token");if(path==="/"){if(isDirectTest){path="/dashboard";}else if(!hasSeenOnboarding){path="/onboarding";}else if(!authToken){path="/login";}else{path="/dashboard";}
updateBrowserUrl(path);}
if(path==="/onboarding"&&hasSeenOnboarding){path=authToken?"/dashboard":"/login";updateBrowserUrl(path);}
const candidateRoute=routes[path]||routes["/login"];if(candidateRoute.authRequired&&!authToken){path="/login";updateBrowserUrl(path);}
if((path==="/login"||path==="/register")&&authToken){path="/dashboard";updateBrowserUrl(path);}
const route=routes[path]||routes["/login"];if(typeof updateActiveNavItem==="function"){updateActiveNavItem(path);}
const appHeader=document.getElementById("app-header");const appNav=document.getElementById("app-navigation");if(appHeader)appHeader.style.display=route.fullScreen?"none":"";if(appNav)appNav.style.display=route.fullScreen?"none":"";const appContent=document.getElementById("app-content");if(!appContent)return;appContent.scrollTop=0;window.scrollTo(0,0);const isFirstPaint=!appContent.innerHTML.trim();if(!isFirstPaint){appContent.style.opacity="0";appContent.style.transition="opacity 0.15s ease";}
const viewFile=route.subview||route.screen;const viewUrl=route.screen==="onboarding"||route.screen==="auth"?`/src/screens/${route.screen}/${viewFile}.html?v=38`:`/src/screens/${route.screen}/${viewFile}.html?v=${Date.now()}`;try{const[response]=await Promise.all([fetch(viewUrl),ensureScreenStylesheet(route.screen),]);if(!response.ok){throw new Error(`No se pudo cargar la vista: ${route.screen}/${viewFile}.html`);}
const html=await response.text();if(isFirstPaint){appContent.innerHTML=html;appContent.scrollTop=0;appContent.style.opacity="1";await loadScreenController(route);}else{setTimeout(async()=>{appContent.innerHTML=html;appContent.scrollTop=0;appContent.style.opacity="1";await loadScreenController(route);},100);}}catch(error){console.error("[Router] Error cargando vista:",error);appContent.innerHTML=`<p class="error-message">Error al cargar la pantalla.</p>`;appContent.style.opacity="1";}}
async function loadScreenController(route){const routerInstance={navigate:navigateTo,current:getCurrentRoute};const appContent=document.getElementById("app-content");if(!appContent)return;switch(route.screen){case "onboarding":{try{const module=await import("../screens/onboarding/onboarding.js?v=31");if(typeof module.initOnboarding==="function"){module.initOnboarding(routerInstance);}}catch(err){console.warn("[Router] Controlador onboarding.js no inicializado:",err);}
break;}
case "ranking":{try{const module=await import(`../screens/ranking/ranking.js?t=${Date.now()}`);if(typeof module.initRanking==="function"){module.initRanking(routerInstance);}}catch(err){console.warn("[Router] Controlador ranking.js no inicializado:",err);}
break;}
case "auth":{try{const module=await import("../screens/auth/auth.js?v=40");if(typeof module.initAuth==="function"){module.initAuth(route.subview,routerInstance);}
if(route.subview!=="register"){setTimeout(ensureGoogleIdentityScript,0);}}catch(err){console.warn("[Router] Controlador auth.js no inicializado:",err);}
break;}
case "dashboard":{try{const module=await import(`../screens/dashboard/dashboard.js?t=${Date.now()}`);if(typeof module.initDashboard==="function"){module.initDashboard(routerInstance);}else if(typeof module.initHomeView==="function"){module.initHomeView(routerInstance);}}catch(err){console.warn("[Router] Controlador dashboard.js no inicializado:",err);}
break;}
case "history":{try{const module=await import(`../screens/history/history.js?t=${Date.now()}`);if(typeof module.initHistory==="function"){module.initHistory(routerInstance);}else if(typeof module.initHistoryView==="function"){module.initHistoryView(routerInstance);}}catch(err){console.warn("[Router] Controlador history.js no inicializado:",err);}
break;}
case "market":{try{const module=await import(`/src/screens/market/market.js?t=${Date.now()}`);if(typeof module.renderMarketScreen==="function"){module.renderMarketScreen(appContent,routerInstance);}else{console.warn("[Router] renderMarketScreen no se encontró en market.js");}}catch(err){console.error("[Router] Error crítico al importar market.js:",err);}
break;}
case "comparison":{try{const module=await import(`../screens/comparison/comparison.js?t=${Date.now()}`);const hashQuery=window.location.hash.includes("?")?window.location.hash.split("?")[1]:"";const mergedParams=new URLSearchParams(window.location.search);if(hashQuery){const hashSearchParams=new URLSearchParams(hashQuery);for(const[k,v]of hashSearchParams.entries()){mergedParams.set(k,v);}}
const urlParams=Object.fromEntries(mergedParams);if(typeof module.renderComparisonScreen==="function"){module.renderComparisonScreen(appContent,routerInstance,urlParams);}}catch(err){console.warn("[Router] Controlador comparison.js no inicializado:",err);}
break;}
case "admin":{try{const module=await import(`../screens/admin/players-admin.js?t=${Date.now()}`);if(typeof module.renderPlayersAdminScreen==="function"){module.renderPlayersAdminScreen(appContent,routerInstance);}}catch(err){console.warn("[Router] Controlador players-admin.js no inicializado:",err);}
break;}
case "profile":{try{const module=await import(`../screens/profile/profile.js?t=${Date.now()}`);if(typeof module.initProfile==="function"){module.initProfile(routerInstance);}else if(typeof module.initProfileView==="function"){module.initProfileView(routerInstance);}}catch(err){console.warn("[Router] Controlador profile.js no inicializado:",err);}
break;}
case "matchmaking":{try{const module=await import(`../screens/matchmaking/matchmaking.js?t=${Date.now()}`);if(typeof module.initMatchmaking==="function"){module.initMatchmaking(routerInstance);}}catch(err){console.warn("[Router] Controlador matchmaking.js no inicializado:",err);}
break;}
case "lineup":{try{const module=await import(`../screens/lineup/lineup.js?t=${Date.now()}`);if(typeof module.initLineup==="function"){module.initLineup(routerInstance);}}catch(err){console.warn("[Router] Controlador lineup.js no inicializado:",err);}
break;}
case "match":{try{const module=await import(`../screens/match/match.js?t=${Date.now()}`);if(typeof module.initMatch==="function"){module.initMatch(routerInstance);}else if(typeof module.initMatchDetailView==="function"){module.initMatchDetailView(routerInstance);}}catch(err){console.warn("[Router] Controlador match.js no inicializado:",err);}
break;}
default:console.debug(`[Router] Sin controlador específico para pantalla: ${route.screen}`,);break;}}
function loadStylesheetOnce(basePath,versionQuery="v=30"){const existing=document.querySelector(`link[href*="${basePath}"]`);if(existing)return Promise.resolve();return new Promise((resolve)=>{const link=document.createElement("link");link.rel="stylesheet";link.href=`${basePath}?${versionQuery}`;const timer=setTimeout(resolve,2500);link.onload=()=>{clearTimeout(timer);resolve();};link.onerror=()=>{clearTimeout(timer);resolve();};document.head.appendChild(link);});}
function ensureGoogleIdentityScript(){if(document.querySelector('script[src*="accounts.google.com/gsi/client"]'))return;const script=document.createElement("script");script.src="https://accounts.google.com/gsi/client";script.async=true;script.defer=true;document.body.appendChild(script);}
function ensureScreenStylesheet(screenName){if(!screenName)return Promise.resolve();if(screenName==="onboarding"){if(document.querySelector('link[href*="main.min.css"], link[href*="main.css"]')){return Promise.resolve();}
return loadStylesheetOnce("/src/styles/screens/onboarding.css","v=31");}
return Promise.all([loadStylesheetOnce("/src/styles/components.css","v=29"),loadStylesheetOnce("/src/components/modal/modal.css","v=19"),loadStylesheetOnce(`/src/styles/screens/${screenName}.css`,"v=36"),]);}
function bootstrapRouter(){if(typeof window!=="undefined"){if(window.__fantasyRouterBootstrapped)return;window.__fantasyRouterBootstrapped=true;}
try{if(authService&&typeof authService.initAuthState==="function"){authService.initAuthState();}}catch(err){console.warn("[Auth] Error inicializando sesión:",err);}
if(typeof renderNavigation==="function"){renderNavigation();}
initRouter();}
if(typeof document!=="undefined"){if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",bootstrapRouter);}else{bootstrapRouter();}}